"use client";

import * as React from "react";
import { Drawer as DrawerPrimitive } from "vaul";
import { cn } from "@/lib/utils";
import { withDirectionalPortal } from "@/components/ui/direction-provider";

const Drawer = ({ shouldScaleBackground = true, ...props }: React.ComponentProps<typeof DrawerPrimitive.Root>) => (
  <DrawerPrimitive.Root shouldScaleBackground={shouldScaleBackground} {...props} />
);
Drawer.displayName = "Drawer";

const DrawerTrigger = DrawerPrimitive.Trigger;
const DrawerPortal = withDirectionalPortal(DrawerPrimitive.Portal);
const DrawerClose = DrawerPrimitive.Close;

const DrawerOverlay = React.forwardRef<
  React.ElementRef<typeof DrawerPrimitive.Overlay>,
  React.ComponentPropsWithoutRef<typeof DrawerPrimitive.Overlay>
>(({ className, ...props }, ref) => (
  <DrawerPrimitive.Overlay ref={ref} className={cn("fixed inset-0 z-overlay bg-scrim", className)} {...props} />
));
DrawerOverlay.displayName = DrawerPrimitive.Overlay.displayName;

const DrawerContent = React.forwardRef<
  React.ElementRef<typeof DrawerPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof DrawerPrimitive.Content>
>(({ className, children, onOpenAutoFocus, ...props }, ref) => {
  /**
   * Focus entry. Measured in Chromium with the drawer open: focus was still on the trigger — which by
   * then sits inside a subtree `aria-hidden="true"`, because the drawer hides the page behind it. So a
   * screen-reader user opened the drawer and was left on an element their assistive technology had just
   * been told does not exist. Tab recovered on the next keystroke; the destination on open did not.
   *
   * Every other modal surface in the family moves focus into the portal on open. `vaul` suppresses that
   * deliberately, to stop a mobile keyboard appearing whenever a drawer with a field in it opens, and
   * that reason is good — so this focuses the panel itself rather than the first thing inside it. A
   * container is not a text field: it opens no keyboard, it gives the screen reader the drawer's own
   * heading to announce, and Tab from there walks the drawer's contents in order.
   *
   * Notably, axe does *not* report this. Its `aria-hidden-focus` rule excuses an aria-hidden page
   * whenever a modal dialog is open, wherever focus actually is — so the open-state scan that found the
   * Popover naming defect is blind to this one. Focus entry needs its own assertion, which is why
   * a11y-browser now carries one.
   */
  const panel = React.useRef<HTMLDivElement | null>(null);
  const setRefs = (node: HTMLDivElement | null) => {
    panel.current = node;
    if (typeof ref === "function") ref(node);
    else if (ref) (ref as React.MutableRefObject<HTMLDivElement | null>).current = node;
  };

  return (
    <DrawerPortal>
      <DrawerOverlay />
      <DrawerPrimitive.Content
        ref={setRefs}
        tabIndex={-1}
        // `onOpenAutoFocus` and not a mount effect: the focus scope underneath runs after mount, so an
        // effect that focuses the panel is overwritten a tick later and the fix silently does nothing
        // (measured — the first attempt here was exactly that). This is the moment the primitive offers.
        //
        // Composed with the caller's handler and destructured out of the spread below: with `{...props}`
        // trailing, any `onOpenAutoFocus` a consumer passes — even one that only logs — would replace this
        // one outright, and since vaul suppresses auto-focus otherwise, focus would be left on the
        // now-hidden trigger and the defect would be back. A caller who calls `preventDefault` themselves
        // is taking focus over deliberately, so that decision stands and the panel is left alone.
        onOpenAutoFocus={(event) => {
          onOpenAutoFocus?.(event);
          if (event.defaultPrevented) return;
          event.preventDefault();
          panel.current?.focus();
        }}
        className={cn(
          "fixed inset-x-0 bottom-0 z-overlay mt-24 flex h-auto flex-col rounded-t-[10px] border bg-background font-sans",
          "outline-none",
          className,
        )}
        {...props}
      >
        <div className="mx-auto mt-4 h-2 w-[100px] rounded-full bg-muted" />
        {children}
      </DrawerPrimitive.Content>
    </DrawerPortal>
  );
});
DrawerContent.displayName = "DrawerContent";

const DrawerHeader = ({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) => (
  <div className={cn("grid gap-1.5 p-4 text-center sm:text-start", className)} {...props} />
);
DrawerHeader.displayName = "DrawerHeader";

const DrawerFooter = ({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) => (
  <div className={cn("mt-auto flex flex-col gap-2 p-4", className)} {...props} />
);
DrawerFooter.displayName = "DrawerFooter";

const DrawerTitle = React.forwardRef<
  React.ElementRef<typeof DrawerPrimitive.Title>,
  React.ComponentPropsWithoutRef<typeof DrawerPrimitive.Title>
>(({ className, ...props }, ref) => (
  <DrawerPrimitive.Title ref={ref} className={cn("text-lg font-semibold leading-none tracking-tight", className)} {...props} />
));
DrawerTitle.displayName = DrawerPrimitive.Title.displayName;

const DrawerDescription = React.forwardRef<
  React.ElementRef<typeof DrawerPrimitive.Description>,
  React.ComponentPropsWithoutRef<typeof DrawerPrimitive.Description>
>(({ className, ...props }, ref) => (
  <DrawerPrimitive.Description ref={ref} className={cn("text-sm text-muted-foreground", className)} {...props} />
));
DrawerDescription.displayName = DrawerPrimitive.Description.displayName;

export {
  Drawer,
  DrawerPortal,
  DrawerOverlay,
  DrawerTrigger,
  DrawerClose,
  DrawerContent,
  DrawerHeader,
  DrawerFooter,
  DrawerTitle,
  DrawerDescription,
};

import { type ClassValue, clsx } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

// The Material type-scale utilities (`text-label-md`, `text-body-sm`, …) come
// from `fontSize` in tailwind.config.ts. Without this, tailwind-merge reads them
// as text *colours* and drops a real colour class (`text-primary-foreground`).
const twMerge = extendTailwindMerge({
  extend: {
    classGroups: {
      "font-size": [
        {
          text: [
            "display-lg", "display-md", "display-sm",
            "headline-lg", "headline-md", "headline-sm",
            "title-lg", "title-md", "title-sm", "title-dialog",
            "label-lg", "label-md", "label-sm",
            "body-lg", "body-md", "body-sm",
          ],
        },
      ],
    },
  },
});

/** Merges Tailwind class names, resolving conflicts (clsx + tailwind-merge). */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/**
 * Keeps the keyboard somewhere useful when a control removes the row it lives in.
 *
 * A remove button inside a chip or a list row destroys itself. Nothing then holds focus, so the
 * browser drops it on `<body>` and the next Tab starts again from the top of the document — a
 * keyboard user clearing three chips is sent back to the beginning after each one.
 *
 * Call this from the removing control's own handler, with the control and a selector that matches
 * one peer per removable row. The surviving peer is chosen BEFORE the removal, from document order:
 * the next row's control, or the previous one when the last row goes. It is focused once the
 * removal has actually happened AND left the keyboard stranded — so a handler
 * that removes nothing, or that moves focus somewhere of its own, keeps the focus it chose.
 *
 * @param trigger the control that was activated
 * @param peerSelector a selector matching the equivalent control on every row, e.g. "[data-kx-remove]"
 * @param options.scope where to look for peers; defaults to the trigger's parent list or its document
 * @param options.fallback where to go when no row survives — a chip group's own input, say
 *
 * Limit: the removal is expected to commit within a microtask or the next animation frame, which is
 * what a React state update from a click does. A removal awaited behind a network call lands later
 * than that, and its focus is the caller's to manage.
 */
export function focusAfterRemoval(
  trigger: HTMLElement | null | undefined,
  peerSelector: string,
  options: { scope?: HTMLElement | null; fallback?: HTMLElement | null } = {},
): void {
  if (!trigger?.isConnected) return;
  const scope = options.scope ?? trigger.closest("ul, ol, [data-kx-removable-group]") ?? trigger.ownerDocument.body;
  const peers = Array.from(scope.querySelectorAll<HTMLElement>(peerSelector));
  const here = peers.indexOf(trigger);
  const survivor = here < 0 ? null : (peers[here + 1] ?? peers[here - 1] ?? null);
  const target = survivor ?? options.fallback ?? null;
  if (!target) return;

  const settle = () => {
    // The trigger is still there: nothing was removed, so nothing should move.
    if (trigger.isConnected) return false;
    // And step in only where the removal actually stranded the keyboard. A handler that moved focus
    // somewhere of its own — the input a chip group is typed into, say — made a deliberate choice,
    // and that choice wins. Stranded means focus fell back to the document, which is what a browser
    // does when the focused element is taken out of the tree.
    const doc = trigger.ownerDocument;
    const active = doc.activeElement;
    const stranded = !active || active === doc.body || active === doc.documentElement || !active.isConnected;
    if (!stranded) return true;
    if (target.isConnected) target.focus();
    return true;
  };
  queueMicrotask(() => {
    if (settle()) return;
    if (typeof requestAnimationFrame === "function") requestAnimationFrame(settle);
  });
}
